      BRAVE_MCP_HOST: "0.0.0.0"
      BRAVE_MCP_PORT: {{env.BRAVE_MCP_PORT}}
      BRAVE_MCP_ENABLED_TOOLS: {{env.BRAVE_MCP_ENABLED_TOOLS}}
